fn pair(a:i32,b:i32)->i32 { a*100+b }
fn sum(n:i32)->i32 {
 let mut i=0; let mut total=0;
 loop {
  i=i+1;
  if i==n { break total; }
  if i%2==0 { continue; }
  total=total+i;
 }
}
fn main() {
 if sum(4)==4 { println!("sum ok"); }
 let x = loop { let unused = pair(37, { break 49; }); };
 if x==49 { println!("call unwind ok"); }
 let y = 37 + (loop { break 49; });
 if y==86 { println!("outer temporary ok"); }
 let mut i=0;
 while i<4 { i=i+1; let unused=37+{continue;0}; }
 if i==4 { println!("continue unwind ok"); }
 let z=loop { loop { break; } break true; };
 if z { println!("nested targets ok"); }
 if true { 37 } else { 49 };
 { 37 };
 println!("discard ok");
}

